// ── Gradients and patterns ───────────────────────────────────────────────────────────────

function defsFor(uid: string, palette: Palette, glowR: number): string {
  const panelH = SKIRT - RAIL - 3
  return (
    linearY(`${uid}-ceil`, TOP, CEIL, [
