    across(`${uid}-wax`, [
      [0, '#e8d6b8'],
      [0.45, '#fbf0da'],
      [1, '#b89c7c'],
    ]) +
    candleDefs(uid) +
    across(`${uid}-shade`, [
      [0, '#c98a4c'],
      [0.5, '#e6b06a'],
      [1, '#a0643a'],
    ]) +
    linearY(`${uid}-night`, WIN.y0, WIN.y1, [
      [0, '#0e1326'],
      [0.6, '#1a2340'],
      [1, '#2a3354'],
    ]) +
    linearY(`${uid}-frost`, WIN.y1 - 22, WIN.y1, [
      [0, '#e8eef8', 0],
      [1, '#e8eef8', 0.3],
    ]) +
    linearX(`${uid}-curtain`, 220, 320, [
      [0, '#6a2e38'],
      [0.25, '#4e2430'],
      [0.75, '#3e1c26'],
      [1, '#4a2230'],
    ]) +
    linearX(`${uid}-velvet`, 212, 258, [
      [0, '#7e3a38'],
