    `<circle cx="${cx}" cy="${y}" r="12" fill="none" stroke="#121018" stroke-width="2.4"/><circle cx="${cx}" cy="${y}" r="10.4" fill="none" stroke="#b8c2d4" stroke-width="0.6" opacity="0.65"/>` +
