  const fx = x + 42
  return (
    `<ellipse cx="${x + 21}" cy="${y + 12.5}" rx="34" ry="2.6" fill="#0d0b12" opacity="0.45"/>` +
    wheel(x) +
    wheel(fx) +
    `<path d="M${x - 12.5} ${y - 1}A13 13 0 0 1 ${x + 9} ${y - 9.5}M${x + 31} ${y - 8}A13 13 0 0 1 ${x + 53} ${y - 2}" fill="none" stroke="#e5d9c8" stroke-width="1.4"/>` +
